def _count_markdown_bullets_outside_fences(text: str) -> int:
    in_fence = False
    count = 0
    for line in text.splitlines():
        if line.lstrip().startswith("```"):
            in_fence = not in_fence
            continue
        if not in_fence and line.startswith("- "):
            count += 1
    return count


